// Sync the OsakaNights design profile into the app.
//
//   .design-profiles/<name>/theme.css          -> src/index.css (between the PROFILE markers)
//   .design-profiles/<name>/design-tokens.json -> src/theme/plotly.json (surface.plotly, hex per mode)
//
// Built by the design-profiles skill (jpeakai/skills, feat/design-profiles-plan).
// Never compute colours at load: the app reads these generated files as they are.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, "../..")
const name = readFileSync(resolve(root, ".design-profiles/.default-profile"), "utf8").trim()
const profile = resolve(root, ".design-profiles", name)

// ---- CSS: copy :root and .dark blocks; fonts load via <link> in index.html.
const css = readFileSync(resolve(profile, "theme.css"), "utf8")
const blocks = css
  .split("\n")
  .filter((l) => !l.startsWith("@import"))
  .filter((l) => !/^\s*--font-(sans|heading|mono):/.test(l)) // set in @theme inline instead
  .join("\n")
  .trim()
const indexPath = resolve(root, "frontend/src/index.css")
const index = readFileSync(indexPath, "utf8")
const START = "/* PROFILE:START (generated by scripts/sync-theme.mjs, do not edit) */"
const END = "/* PROFILE:END */"
const i = index.indexOf(START)
const j = index.indexOf(END)
if (i < 0 || j < 0) throw new Error(`markers missing from ${indexPath}`)
writeFileSync(indexPath, `${index.slice(0, i + START.length)}\n${blocks}\n${index.slice(j)}`)

// ---- Plotly: resolve aliases in surface.plotly to hex, per mode.
const doc = JSON.parse(readFileSync(resolve(profile, "design-tokens.json"), "utf8"))
const ctx = doc.modifiers.mode.contexts
const get = (o, path) => path.split(".").reduce((a, k) => a?.[k], o)
function hex(mode, v) {
  if (typeof v === "string" && v.startsWith("{")) {
    const node = get(ctx[mode][0], v.slice(1, -1))
    if (!node) throw new Error(`unresolved ${v} in ${mode}`)
    return hex(mode, node)
  }
  if (v && typeof v === "object" && "$value" in v) return hex(mode, v.$value)
  if (v && typeof v === "object" && "hex" in v) return v.hex
  if (v && typeof v === "object")
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, hex(mode, x)]))
  return v
}
const plotly = {}
for (const mode of Object.keys(ctx)) {
  const p = hex(mode, ctx[mode][0].surface.plotly)
  for (const k of ["colorway", "sequential", "muted"]) p[k] = Object.values(p[k])
  plotly[mode] = p
}
const seed = JSON.parse(readFileSync(resolve(profile, "seed.json"), "utf8"))
plotly.font = { body: seed["font.body"], mono: seed["font.mono"], display: seed["font.display"] }
plotly.defaultMode = seed["mode.default"]
mkdirSync(resolve(root, "frontend/src/theme"), { recursive: true })
writeFileSync(resolve(root, "frontend/src/theme/plotly.json"), JSON.stringify(plotly, null, 2) + "\n")
console.log(`synced profile ${name}: index.css vars, src/theme/plotly.json`)
